// Abort BEFORE burning a partial episode — an episode renders every scene (💸).
// Mirrors MIN_TOKEN_BALANCE=2000 in show/Horoscopes/show.env.
// Doubles as the config preflight, so an unfilled Show config fails here in
// seconds — not after the story step.
const cfg = $('Show config').first().json;
if (!cfg.campaignId) throw new Error('Show config: campaignId is empty — set it to a campaign id the API credential\'s account owns');
if (!cfg.userId) throw new Error('Show config: userId is empty — set it to the YakYak user id the API credential belongs to');
const user = $json;
if (user.tokenBalance === undefined) throw new Error('could not fetch the user record — check Show config userId and the "YakYak API" credential (' + (user.error?.message || 'no tokenBalance in response') + ')');
const balance = Number(user.tokenBalance || 0);
const min = Number(cfg.minTokenBalance || 2000);
if (balance < min) throw new Error('token balance ' + balance + ' is below the ' + min + ' minimum — top up before generating an episode');
return [{ json: { balance } }];

// Deterministic weekly story — JS port of show/Horoscopes/compute.py, replacing
// the whole prompt/model stage: no Claude call, no Anthropic credential, no
// network. Same 14-scene structure and house rules (unique advice per sign,
// "This Week's Advice for <Sign>;" spoken openers, no trailing period). One
// deliberate difference: picks are keyed by FNV-1a + mulberry32 instead of
// Python's sha256, so for the same ISO week the WORDING differs from a
// showrunner run — but it is equally deterministic (same week in -> same story out).
const GURU = 'The Cosmic Guru';
const SIGNS = [
  ['Aries', 'the Ram', 'Fire'],
  ['Taurus', 'the Bull', 'Earth'],
  ['Gemini', 'the Twins', 'Air'],
  ['Cancer', 'the Crab', 'Water'],
  ['Leo', 'the Lion', 'Fire'],
  ['Virgo', 'the Maiden', 'Earth'],
  ['Libra', 'the Scales', 'Air'],
  ['Scorpio', 'the Scorpion', 'Water'],
  ['Sagittarius', 'the Archer', 'Fire'],
  ['Capricorn', 'the Goat', 'Earth'],
  ['Aquarius', 'the Water-Bearer', 'Air'],
  ['Pisces', 'the Fish', 'Water'],
];
const DOMAINS = ['love', 'work', 'money', 'health', 'friendship', 'creativity', 'travel', 'rest'];
const MOODS = ['bold', 'cautious', 'playful', 'restless', 'grounded', 'tender', 'sharp', 'dreamy'];
// Advice is DEALT WITHOUT REPLACEMENT across the 12 signs, so this bank must
// hold at least 12 distinct lines — same bank as compute.py.
const ADVICE = [
  'say the thing you keep rehearsing',
  'let one plan quietly fall through',
  'spend the small money, save the big yes',
  "answer the message you've been dodging",
  "leave the party while it's still good",
  'make the list, then ignore item one',
  'trust the slower of your two instincts',
  'close the tab, open the window',
  'keep the promise you made to yourself',
  'ask the question you already know the answer to',
  'let the silence do the talking',
  'finish the thing that is almost done',
  'give the favor before it is asked for',
  'walk the long way home on purpose',
  'save your yes for the thing that scares you',
  'forgive the version of you from last week',
  "cancel the plan you're already dreading",
  'send the thank-you a day too early',
  'keep one secret just for yourself',
  'let the small mistake stay small',
  'choose the chair facing the door',
  'say no without the paragraph after it',
  'take the photo, then put the phone away',
  'start the boring task first',
  'let them be wrong about you',
  'pay for the better coffee today',
  'write it down before you trust your memory',
  'leave room in the day for nothing',
  "call the person, don't text them",
  "quit the game while you're ahead",
  'hold the door open one more minute',
  'let the compliment land without deflecting',
  'pack lighter than you think you need',
  'sleep on the angry reply',
  'take the smaller portion of the blame',
  'say the name of the thing you fear',
  'let one chore wait until tomorrow',
  'take the scenic route to nowhere',
  'tell them the good news first',
  'keep the receipt, lose the regret',
  'stop explaining once they understand',
  'choose the harder of two easy roads',
  'let the old grudge get off here',
  'ask for help before you need it',
  'spend an hour doing nothing useful',
  'say less in the meeting today',
  'trust the note you left yourself',
  'unfollow the thing that makes you smaller',
  'finish the book before you start the new one',
  'keep your word on the small ask',
  "take the stairs you've been avoiding",
  'say the apology without the "but"',
  'let the plan change without panicking',
  'give the last word away on purpose',
  'turn the radio off and just drive',
  'choose curiosity over being right',
  "let the bread rise, don't rush it",
  "mail the letter you've been writing",
  'trade one scroll for one walk',
  "let tomorrow's worry stay in tomorrow",
  'drink the water before the coffee',
  "thank the person who can't help you",
  'let the early morning be yours alone',
  'keep the plant you keep forgetting alive',
];
const SETTINGS = [
  'a rooftop where the city hums below',
  'a kitchen at the blue hour before dawn',
  'a crowded train that suddenly empties',
  'a quiet office after everyone has left',
  'a market stall stacked with strange fruit',
  'a shoreline arguing politely with the tide',
  'a stairwell that echoes one floor too far',
  'a garden that has opinions about the weather',
];
const COSMIC = [
  'Mercury drags its feet',
  'the Moon changes its mind',
  'Venus sends a read receipt',
  'Mars taps its foot',
  'Saturn audits the receipts',
  'Jupiter overpromises again',
  'a quiet eclipse clears its throat',
  'the stars file an amended forecast',
];
const ADVICE_OPENERS = [
  "This Week's Advice",
  "This Week's Guidance",
  "This Week's Counsel",
  "This Week's Wisdom",
  'Your Weekly Counsel',
  'Your Weekly Guidance',
  "The Week's Wisdom",
];
const GURU_OUTLOOK = [
  'the week rewards patience over speed for every sign',
  'a slow start hides a strong finish this week',
  'the stars favor honesty over cleverness right now',
  'rest is the assignment before the breakthrough',
  'small kept promises outshine grand new plans',
  'listen twice as often as you speak this week',
  'the brave move this week is the gentle one',
  "let what is ending end, and make room for what's next",
];
const GURU_CLOSING = [
  'let the starlight settle in your bones and walk on',
  'the wheel turns whether you watch or not, so turn with it',
  'carry one ember of the cosmos and let the dark keep the rest',
  'what the stars whispered, let your silence answer',
  'step into the week as through a door only you can see',
  'the tide that pulls you also remembers the way back',
  'hold the omen lightly and it will hold you',
  'the heavens have drawn the map, but the walking is yours',
  'may the constellations keep your name on their tongue',
  'trust the long orbit, even where the path runs dark',
  'let what is written in light stay lighter than your worries',
  'the veil thins for those who move gently, so move gently',
  'gather the small magics and leave the doubt behind',
  'every star you have ever seen has already wished you onward',
  'go where the moon leans and you will not be lost',
  'the sky closes its eye now, so keep yours open to wonder',
];

function h32(s) { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193); } return h >>> 0; }
function mulberry32(a) { return function () { a |= 0; a = (a + 0x6d2b79f5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
const pickB = (bank, ...keys) => bank[h32(keys.join('|')) % bank.length];
// deal `count` DISTINCT items (seeded Fisher-Yates, then the first `count`)
const dealUnique = (bank, count, ...keys) => {
  const rng = mulberry32(h32(keys.join('|') + '|deal'));
  const p = bank.slice();
  for (let i = p.length - 1; i > 0; i--) { const j = Math.floor(rng() * (i + 1)); const t = p[i]; p[i] = p[j]; p[j] = t; }
  return p.slice(0, count);
};
const cap = (s) => (s ? s.charAt(0).toUpperCase() + s.slice(1) : s);

// ISO week (UTC)
const now = new Date();
const t = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
const dow = t.getUTCDay() || 7;
t.setUTCDate(t.getUTCDate() + 4 - dow);
const year = t.getUTCFullYear();
const week = Math.ceil(((t.getTime() - Date.UTC(year, 0, 1)) / 86400000 + 1) / 7);
const ts = now.toISOString();

// one unique advice per sign — dealt without replacement for the whole week
const dealt = dealUnique(ADVICE, SIGNS.length, year, week, 'advice');
const adviceFor = {};
SIGNS.forEach((s, i) => { adviceFor[s[0]] = dealt[i]; });
const outlook = pickB(GURU_OUTLOOK, year, week, 'outlook');
const closing = pickB(GURU_CLOSING, year, week, 'closing');

const out = [];
out.push('# Cosmic Brief — Weekly Horoscopes');
out.push('**Generated (UTC):** ' + ts);
out.push('**For:** ISO week ' + week + ', ' + year);
out.push('');
out.push('## Headlines we drew from:');
out.push("- The Cosmic Guru's outlook: " + outlook);
for (const [name, , element] of SIGNS) {
  out.push('- ' + name + ' (' + element + '): a ' + pickB(MOODS, year, week, name, 'mood') + ' week for ' + pickB(DOMAINS, year, week, name, 'domain'));
}
out.push('');

out.push('## Scene 1 — The Cosmic Guru opens the week');
out.push('**Leading character:** ' + GURU);
out.push('**Dialog:** "This Week\'s Cosmic Outlook; ' + cap(outlook) + '"');
out.push('');
out.push('Exterior of the heavens: ' + pickB(SETTINGS, year, week, 'guru-intro-setting') + ', reimagined as a vast starlit observatory. The Cosmic Guru — a serene celestial sage in a star-woven robe, a constellation haloing their brow — faces the lens like a trusted teacher beginning a lesson. They sweep one hand across the zodiac wheel turning slowly overhead and name the mood of the whole week before any single sign steps forward. The palette is deep indigo and gold; the camera drifts slow and contemplative. This is the frame the rest of the readings hang on — calm, unhurried, certain.');
out.push('');

SIGNS.forEach((sign, offset) => {
  const name = sign[0], persona = sign[1], element = sign[2];
  const domain = pickB(DOMAINS, year, week, name, 'domain');
  const mood = pickB(MOODS, year, week, name, 'mood');
  const advice = adviceFor[name];
  const setting = pickB(SETTINGS, year, week, name, 'setting');
  const cosmic = pickB(COSMIC, year, week, name, 'cosmic');
  const opener = pickB(ADVICE_OPENERS, year, week, name, 'advice-opener');
  out.push('## Scene ' + (offset + 2) + ' — ' + name);
  out.push('**Leading character:** ' + name + ' ' + persona);
  out.push('**Dialog:** "' + opener + ' for ' + name + '; ' + cap(advice) + '"');
  out.push('');
  out.push('Interior/exterior: ' + setting + '. We find ' + name + ' ' + persona + ', a ' + mood + ' ' + element.toLowerCase() + '-sign avatar lit so their accent color glows at the edges. The week\'s transit is plain: ' + cosmic + ', and ' + name + ' feels it in the ' + domain + ' corner of their life. The camera drifts slow and contemplative — this is a reading, not a chase. Around them the scene rhymes with the forecast: small omens, a flickering sign, an object that lands exactly where it was aimed. ' + name + ' weighs the advice to ' + advice + ', and for one held beat we see them decide. Nothing explodes; the drama is internal, the kind a viewer recognizes in themselves. The accent color pulses once as the resolution settles, and the avatar turns toward the lens like a friend who already knows what you\'ll do with the week.');
  out.push('');
});

out.push('## Scene 14 — The Cosmic Guru closes the week');
out.push('**Leading character:** ' + GURU);
out.push('**Dialog:** "Parting Words from the Cosmos; ' + cap(closing) + '"');
out.push('');
out.push('Exterior of the heavens again: ' + pickB(SETTINGS, year, week, 'guru-outro-setting') + ', the zodiac wheel now come full circle behind The Cosmic Guru. The same star-woven sage draws the twelve readings back together, the accent colors of all twelve signs flickering once in the nebula like a roll call. They offer a single parting thought for everyone, hands lowering in a calm blessing as the constellation halo dims. The camera pulls back slow and contemplative until the whole sky is in frame — a quiet button on the week, certain and kind.');

const story = out.join('\n').replace(/\s+$/, '') + '\n';
const socialTitle = ('Cosmic Brief — Week ' + week + ', ' + year).slice(0, 50);
const capBits = ['Cosmic outlook: ' + outlook];
for (const [name, , ] of SIGNS.slice(0, 3)) capBits.push(name + ': a ' + pickB(MOODS, year, week, name, 'mood') + ' week for ' + pickB(DOMAINS, year, week, name, 'domain'));
const socialCaption = capBits.join(' · ').slice(0, 400);
return [{ json: { story, socialTitle, socialCaption, week, year } }];

// Port of storyToDescription() from show/showrunner/story-format.js: drop
// everything before the first '## Scene', collapse each scene's prose to one
// line, append `<Char> says: "<dialog>"`, mapping names through the cast map
// (CAST_ALIASES in show/Horoscopes/show.env). The story markdown comes from the
// deterministic Compute story node (no model in this show), which also
// supplies the social title + caption.
const story = String($json.story || '');
if (!/## Scene/.test(story)) throw new Error('Compute story emitted no "## Scene" blocks — not a story');
const socialTitle = String($json.socialTitle || '').slice(0, 50);
const socialCaption = String($json.socialCaption || '').slice(0, 400);

const ALIASES = {"The Cosmic Guru":"The Cosmic Guru","Aries":"Aries","Taurus":"Taurus","Gemini":"Gemini","Cancer":"Cancer","Leo":"Leo","Virgo":"Virgo","Libra":"Libra","Scorpio":"Scorpio","Sagittarius":"Sagittarius","Capricorn":"Capricorn","Aquarius":"Aquarius","Pisces":"Pisces"};
const mapShort = (name) => { for (const k of Object.keys(ALIASES)) if (name.includes(k)) return ALIASES[k]; return String(name).trim(); };

const lines = story.split(/\r?\n/);
let inScene = false, n = 0, prose = '', character = '', dialog = '';
const parts = [];
const emit = () => {
  if (!inScene) return;
  const p = prose.replace(/[ \t]+/g, ' ').trim();
  const s = mapShort(character);
  parts.push(n === 0 ? '- ' + p + ' ' + s + ' says: "' + dialog + '"' : '\n\n  - ' + p + ' ' + s + ' says: "' + dialog + '"');
  n++;
};
for (const line of lines) {
  if (/^## Scene/.test(line)) { emit(); inScene = true; prose = ''; character = ''; dialog = ''; continue; }
  if (!inScene) continue;
  if (/^\*\*Leading character:\*\*/.test(line)) { character = line.replace(/^\*\*Leading character:\*\*[ \t]*/, ''); continue; }
  if (/^\*\*Dialog:\*\*/.test(line)) { dialog = line.replace(/^\*\*Dialog:\*\*[ \t]*/, '').trim().replace(/^"|"$/g, '').replace(/[.。]$/, ''); continue; }
  if (/^##/.test(line)) { emit(); inScene = false; continue; }
  prose += ' ' + line;
}
emit();
if (!parts.length) throw new Error('no scenes parsed from the story');
const plot = parts.join('');
return [{ json: { plot, socialTitle, socialCaption, scenes: n, story } }];

// Shape the engine call: episode mode in the pinned Cosmic Brief campaign, the
// story as the new episode's plot, optional soundtrack pin. The engine's
// sub-workflow trigger is passthrough — this item IS the payload (same shape
// as the engine webhook's body). Re-delivered same-day stories are diff-aware
// on the engine side, so a duplicate run doesn't re-bill unchanged work.
const cfg = $('Show config').first().json;
if (!cfg.campaignId) throw new Error('Show config: campaignId is empty');
const movie = { plot: $json.plot };
if (cfg.soundtrackAudioPath) {
  movie.soundtrackAudioPath = cfg.soundtrackAudioPath;
  if (cfg.soundtrackVolume) movie.soundtrackVolume = Number(cfg.soundtrackVolume);
}
return [{ json: { target: { mode: 'episode', campaignId: cfg.campaignId }, changes: { movie }, chatWebhookUrl: '' } }];
